window.CF={"maj15": {"id": "maj15", "secs": {"Что изображено": "Фон карты чёрный, без неба и горизонта. В центре на тёмном постаменте сидит на корточках огромная фигура, наполовину человек, наполовину козёл.", "Детали и их смысл": "Многие современные толкователи замечают, что петли цепей на шеях выглядят широкими. Отсюда частое прочтение: цепь можно снять, люди держатся сами.", "Главный принцип": "Дьявол показывает сильное желание или привязанность, где выгода и цена связаны между собой. Деньги, секс, власть и комфорт сами по себе карту не объясняют.", "Карта как человек": "Человек Дьявола сильно чего-то хочет и умеет добиваться желаемого. Он притягателен, убедителен, хорошо замечает чужие слабости.", "Выгода, контроль, влечение и поступки": "Начинающие сливают эти четыре стороны карты в одно слово «зависимость». На практике ответ по ним разный.", "Отношения, брак и семья": "В отношениях Дьявол показывает сильную телесную тягу и интерес, от которого трудно отвлечься. Партнёры могут наслаждаться близостью и открыто договариваться о желаниях, пороком это называть не нужно.", "Работа и проект": "В работе Дьявол показывает доходный контракт, сильную конкуренцию, зависимость от начальника или стремление получить должность любой ценой. На вопрос о предложении выясняйте зарплату, график, штрафы и право отказаться от дополнительных задач.", "Деньги и имущество": "В деньгах карта привлекает внимание к кредитам, крупным желаниям, азарту и расходам ради удовольствия. Человек покупает дорогую вещь в рассрочку, а затем сокращает обязательные платежи.", "Ситуация и развитие событий": "В развитии событий карта показывает усиление желания или давления. Условия становятся привлекательнее, отказаться от них труднее, потому что потрачены годы, деньги, силы.", "Магия и диагностика": "В магической диагностике Дьявол привлекает внимание к зависимости, сильной привязке или борьбе за контроль. Позиция показывает тему, которая забирает силы.", "Перевёрнутое положение (дополнительно)": "Перевёрнутая карта показывает, что привычная связь меняется. Человек замечает цену зависимости и начинает возвращать себе выбор: открывает свой счёт, ищет другую работу, впервые говорит партнёру «нет». В другом вопросе давление прячется за внешне спокойными условиями.", "Сочетания и сравнения": "Сочетания даны с картами уроков 4 и 5.", "Ошибки начинающих": "", "Практика и проверка": ""}, "err": ["сказать по Дьяволу «вы держитесь сами, просто уйдите». Человек услышит упрёк, и разговор о реальных шагах не начнётся.", "считать Дьявола доказательством порчи, измены или преступления. Уточните, какую привязанность описывает позиция и чем её можно проверить.", "объявлять Дьявола «плохим человеком». Карта описывает связь и способ влияния, характер живого человека устанавливается по его поступкам."], "rem": ["Дьявол показывает сильную привязанность и цену, которую человек платит за сохранение связи."], "prac": [["Найдите на карте три детали, по которым видно, что люди похожи на центральную фигуру. Запишите, что это сходство значит для вопроса об участии людей в ситуации.", "Детали: рожки, хвосты, нагота. Уэйт добавляет, что в лицах у людей сохраняется человеческий разум. Вывод: люди участвуют в связи и что-то от неё получают, поэтому вопрос звучит «какую выгоду имеет каждый». Из рисунка не следует, что люди виноваты в своём положении или что им легко уйти."], ["Найдите ошибку в трактовке: «Вопрос о новой работе. Выпал Дьявол. Работа плохая, отказывайтесь».", "Карта не оценивает работу как плохую. Она предлагает найти, чем условия держат человека: зарплатой, штрафом за уход, графиком, зависимостью от руководителя. Верный ответ: «Перед согласием прочитайте договор, выясните, как оплачиваются переработки и можно ли уволиться без штрафа». Если условия честные, высокая оплата остаётся плюсом."], ["Вопрос: «Почему я не могу закрыть кредитную карту?» Выпал Дьявол. Разберите выгоду, цену, удержание и один шаг.", "Выгода: возможность купить сразу то, на что нет денег. Цена: проценты и тревога в конце месяца. Удержание: привычка закрывать картой обычные расходы, на которые не хватает зарплаты. Шаг: месяц записывать траты и найти две статьи, которые можно убрать. Карта показывает механизм, который держит долг. Погасится ли он, решат поступки человека."], ["Сравните Дьявола и Влюблённых на вопросе «Что меня держит в этих отношениях?»", "Влюблённые описывают выбор и связь, которую человек признаёт своей, даже если она трудная. Дьявол описывает связь, где человек чувствует себя на цепи и остаётся из-за денег, страха или влечения, которое сильнее его решения. По рисунку: на Влюблённых над парой ангел и люди свободны, на Дьяволе над парой фигура и люди скованы."]], "ex": ["Ольга Петровна спрашивает, почему дочь Марина не уходит от мужа, который её постоянно унижает. Выпадает Дьявол. Разбор начинается с вопросов. На чьё имя квартира? Работает ли Марина? Кто платит за садик? Выясняется, что квартира мужа, а Марина три года не работает. Дьявол показывает точку крепления: жильё и деньги. Совет матери: перестать уговаривать дочь «просто уйти» и предложить конкретное, например пожить у неё и помочь с работой."], "det": [], "pairs": [], "person": {"Мысли": "Сосредоточенность на предмете желания.", "Чувства": "Сильное влечение, ревность, страх потерять доступ к тому, что нравится.", "Намерения": "Сблизиться, удержать контроль, получить конкретную выгоду.", "Поступки": "Звонки, подарки, давление, уступки, траты ради желаемого."}, "combo": [], "pos": [], "open": "Дьявол показывает связь, которая что-то даёт человеку и одновременно забирает у него часть свободы выбора.", "vis": "На чёрном фоне на постаменте сидит рогатая крылатая фигура с перевёрнутой пятиконечной звездой над лбом. Правая рука поднята ладонью вперёд, левая держит факел пламенем вниз. Цепи от кольца на постаменте идут к шеям обнажённых мужчины и женщины с рожками и хвостами."}, "maj16": {"id": "maj16", "secs": {"Что изображено": "На вершине острой серой скалы стоит высокая каменная башня. Небо вокруг чёрное, в нём плывут серые облака.", "Детали и их смысл": "Порядок взгляда: молния, корона, огонь, падающие люди, скала. Молния даёт причину, всё остальное показывает последствия.", "Главный принцип": "Башня показывает резкое разрушение привычного устройства. Это внезапная новость, срыв договорённости, увольнение или обнаружение проблемы, которую больше нельзя обходить.", "Внезапный срыв и постепенное завершение": "Башню часто путают со Смертью: обе карты говорят о конце прежнего положения. Разница видна уже на рисунке.", "Карта как человек": "В характеристике человека Башня показывает того, кто действует резко, быстро реагирует на кризис или разрушает старые правила. В напряжении он способен высказать всё сразу и оборвать разговор.", "Отношения, брак и семья": "В отношениях Башня даёт крупную ссору, раскрытие обмана или пересмотр прежних договорённостей. Карта не требует автоматически объявлять развод.", "Работа и проект": "В работе Башня показывает неожиданный уход руководителя, закрытие отдела, конфликт или срыв проекта. Проверяйте, что разрушилось: должность, график, контракт или представление о партнёре.", "Деньги и имущество": "В деньгах карта привлекает внимание к внезапным расходам и непрочной финансовой схеме. Банк блокирует счёт для проверки.", "Ситуация и развитие событий": "В позиции настоящего Башня описывает событие, которое уже случилось или происходит сейчас. Человек в шоке, ему нужна ясность о первых шагах.", "Магия и диагностика": "В диагностике Башня показывает пробой привычной защиты, резкое нарушение границ или разрушение старой конструкции. Человек описывает это так: «всё посыпалось сразу», «как будто вышибло почву».", "Перевёрнутое положение (дополнительно)": "Перевёрнутая Башня может показывать затянутый распад или попытку удержать то, что уже трещит. Здание стоит, но в стенах трещины, и человек каждый день подпирает его новыми усилиями. В другом положении она описывает последствия прошедшего кризиса, с которыми человек ещё разбирается.", "Сочетания и сравнения": "Сочетания даны с картами уроков 4 и 5 и с Дьяволом.", "Ошибки начинающих": "", "Практика и проверка": ""}, "err": ["объявлять катастрофой любой выход Башни. Уточните масштаб и сферу вопроса: сломанный ноутбук и банкротство дают одну карту, но разный ответ.", "называть Башню точной датой беды. В позиции будущего она предупреждает о непрочности, которую ещё можно проверить.", "путать Башню и Смерть. Смерть приходит постепенно и видна заранее, Башня бьёт сразу.", "забыть про огонь в окнах. Если читать только молнию, получается «вам не повезло». Огонь изнутри показывает, что причина копилась, и с ней можно работать."], "rem": ["Башня показывает резкий слом прежних условий и необходимость действовать после него."], "prac": [["На рисунке у одного из падающих людей корона на голове, ещё одна корона слетает с крыши. Объясните, что меняет эта деталь в вопросе о руководителе фирмы.", "Корона показывает власть и статус. Её присутствие у падающего человека значит, что положение руководителя не защищает его от удара. В вопросе о руководителе это может быть потеря должности, отказ партнёров, проверка. Из рисунка не следует, что руководитель виноват: молния пришла снаружи. Вину и причину выясняют отдельно."], ["Опишите рабочую ситуацию до и после выхода Башни; назовите событие и первое доступное действие.", "Образец. До: маленькое агентство получает почти всю выручку от одного заказчика. Событие: заказчик расторгает договор за неделю. Первое действие: в тот же день посчитать, на сколько месяцев хватит денег, и написать прежним клиентам. Вывод по карте: огнём в окнах была зависимость от одного заказчика, молнией его уход."], ["Вопрос: «Что будет с моим браком?» Выпала Башня. Человек хочет услышать «да» или «нет» о разводе. Объясните, что карта говорит и чего не говорит.", "Карта говорит, что в браке произошло или назревает резкий поворот, после которого прежний порядок не сохранится. Она не говорит, разведётся ли пара. Нужно уточнить, какое основание оказалось непрочным: деньги, доверие, распределение обязанностей. Решение о будущем брака принимают люди, а расклад помогает увидеть, что нужно обсуждать."], ["Сравните Башню и Смерть на вопросе о квартире, которую семья снимает восемь лет.", "Смерть: хозяин предупреждает, что через три месяца продаёт квартиру. Есть время искать новое жильё и спокойно собрать вещи. Башня: соседи сверху затопили квартиру, жить в ней нельзя, переезжать нужно на этой неделе. В обоих случаях жизнь в этой квартире заканчивается, но скорость и первое действие разные."]], "ex": ["Наталья случайно увидела в банковском приложении мужа кредит на полмиллиона, о котором он молчал год. Скандал, муж ночует у брата. Наталья спрашивает о будущем брака, выпадает Башня. Карта описывает сам удар: рухнуло доверие в вопросе денег. Что дальше, она не решает. Разбор начинается с фактов: на что взят кредит, кто его платит, есть ли другие долги. Пара может развестись, а может впервые сесть и составить общий бюджет. Это покажут следующие позиции и поступки обоих."], "det": [], "pairs": [], "person": {"Мысли": "Внезапное понимание, что прежняя картина не складывается.", "Чувства": "Шок, злость, испуг.", "Намерения": "Готовность резко изменить условия.", "Поступки": "Ищите конкретный разрыв, отказ, срочное действие."}, "combo": [["Башня и Дьявол", "Рухнула связь, которая держала. Человек теряет то, к чему был привязан: работу, отношения, источник денег."], ["Башня и Смерть", "Обе связаны с окончанием прежнего состояния. Башня подчёркивает внезапный слом и потрясение, Смерть показывает завершение этапа."], ["Башня и Правосудие", "Последствия сорванных договорённостей, суд, проверка, вскрывшиеся документы."], ["Башня и Колесница", "Движение прерывается, и маршрут придётся пересмотреть."], ["Башня и Император", "Рушится порядок, власть, структура. Уходит начальник, разваливается система правил в семье."], ["Башня и Колесо Фортуны", "Колесо описывает смену обстоятельств, которую можно пережить и подстроиться. Башня описывает сам удар."], ["Башня и Повешенный", "После удара наступает вынужденная остановка. Человек не может двигаться дальше, пока не разберётся."], ["Башня и Умеренность", "После разрушения начинается постепенное восстановление. Умеренность подсказывает, что собирать новое нужно по частям."], ["Башня и Дурак", "Резкий прыжок в неизвестное. Иногда человек сам ломает стены, чтобы уйти, без плана на следующий день."], ["Башня и Влюблённые", "Раскрылось то, что касается выбора партнёра. Измена, тайные отношения, решение, которое больше нельзя откладывать."], ["Башня и Отшельник", "После удара человек уходит в себя, отказывается от общения, разбирается в одиночку."]], "pos": [], "open": "Башня показывает, как резко рушится конструкция, которая казалась прочной, и что после этого придётся делать.", "vis": "На скале стоит каменная башня, в её вершину бьёт молния. Корона слетает с крыши, из пролома и окон вырывается огонь. Два человека падают вниз головой, у одного на голове корона. На чёрном небе облака и жёлтые капли, похожие на язычки пламени."}, "maj17": {"id": "maj17", "secs": {"Что изображено": "Небо светлое, голубое. В центре сверху горит большая жёлтая звезда с восемью лучами.", "Детали и их смысл": "Порядок взгляда: большая звезда, малые звёзды, женщина, два потока воды, птица на дереве. Звёзды задают направление, женщина показывает, что делается внизу, на земле.", "Ориентир, надежда и действия": "На Звезде видны три разных уровня, и начинающие часто сливают их в одно слово «надежда». Тогда карта превращается в обещание «всё будет хорошо», а это ученику ничего не даёт.", "Главный принцип": "Звезда показывает надежду, открытость будущему и возможность постепенно восстановить силы после трудного периода. Она помогает увидеть направление и продолжать действия, даже когда результат ещё далеко.", "Восстановление после завершившегося периода": "Звезда часто выпадает человеку, у которого закончился трудный этап. Это может быть развод, увольнение, болезнь, закрытие дела.", "Карта как человек": "Человек Звезды открыто говорит о намерениях и способен поддержать другого. Он видит перспективу и делится идеями, рядом с ним другим тоже хочется что-то начать.", "Отношения, брак и семья": "В отношениях Звезда показывает искренний интерес и постепенное сближение. Люди открыты друг другу, говорят о планах, не играют.", "Работа и проект": "В работе Звезда связана с творчеством, публичностью, обучением и долгим проектом, который становится заметным. Мастер регулярно публикует портфолио и постепенно получает заказы.", "Деньги и имущество": "В деньгах карта показывает возможность улучшения, когда за планом следуют действия и учёт расходов. После долгов человек начинает понемногу откладывать.", "Ситуация и развитие событий": "В позиции настоящего Звезда описывает время после трудностей: стало спокойнее, появилась ясность. В позиции будущего она показывает, что при продолжении действий ситуация будет улучшаться.", "Магия и диагностика": "В диагностике Звезда указывает на восстановление и возвращение чувствительности после тяжёлого периода. Человек снова видит сны, чувствует вкус еды, хочет общаться.", "Перевёрнутое положение (дополнительно)": "Перевёрнутая Звезда показывает разочарование или трудность увидеть перспективу. Человек говорит: «Я ничего не хочу», «Не вижу смысла». Ориентир пропал, остались только обязанности.", "Сочетания и сравнения": "Сочетания даны с картами уроков 4 и 5, с Дьяволом и Башней.", "Ошибки начинающих": "", "Практика и проверка": ""}, "err": ["читать Звезду только по верхней половине карты. Без кувшинов и воды ответ превращается в «ждите исполнения желания», хотя женщина на рисунке занята работой.", "обещать мгновенное исполнение желания. Выясните, какое действие приближает человека к цели.", "путать ориентир и результат. Звезда показывает, куда идти. О том, что человек уже пришёл, она не говорит.", "читать наготу фигуры как тему секса. На этой карте нагота означает открытость и отсутствие защиты, сюжет о близости ищите на других картах.", "называть Звезду знаком славы. Публичность здесь бывает, но она приходит через долгую работу, которую видят другие."], "rem": ["Звезда показывает ориентир, надежду и постепенное восстановление."], "prac": [["Найдите на рисунке, куда смотрит женщина: на большую звезду или на воду. Объясните, что это меняет в трактовке.", "Женщина смотрит вниз, на воду, которую льёт. Звезда горит над ней, но она не разглядывает её. Вывод: ориентир задаёт направление, а внимание человека занято действием. В трактовке это значит, что ответ по Звезде обязательно включает конкретный шаг. Из рисунка не следует, что цель достигнута или будет достигнута к сроку."], ["Запишите один долгий план и два действия, которые вы способны выполнить на этой неделе.", "Образец. План: через два года работать переводчиком с испанского. Действия: в понедельник записаться на курс, в субботу перевести одну статью и попросить знакомого проверить. Проверьте свою запись: оба действия должны иметь срок и результат, который можно увидеть. «Больше читать по-испански» не годится, «прочитать главу книги к пятнице» годится."], ["Найдите ошибку: «Вопрос: вернётся ли ко мне бывший? Выпала Звезда. Да, вернётся, у вас есть надежда».", "Ошибка в том, что надежду спрашивающего выдают за поступок другого человека. Звезда может описывать чувства спрашивающего: он надеется и видит в прошлых отношениях ориентир. О поступках бывшего партнёра карта в этой позиции не сообщает. Точный ответ: «Карта показывает вашу надежду. Давайте посмотрим, какие шаги делает другой человек и что делаете вы»."], ["Сравните Звезду и Умеренность на вопросе о восстановлении после развода.", "Умеренность описывает, как человек выстраивает новый порядок: график встреч с детьми, распределение денег, отношения с бывшим супругом без ссор. Звезда описывает, куда он хочет прийти: новая жизнь, в которой есть место радости и планам. Вместе они дают полный ответ: Звезда даёт направление, Умеренность показывает, как настроить жизнь по дороге."]], "ex": ["Виктор восемь лет держал автосервис и закрыл его, когда арендодатель поднял плату вдвое. Полгода он почти не выходил из дома и злился на себя. Он спрашивает, есть ли у него будущее в профессии, выпадает Звезда. Ориентир: Виктор хочет снова работать с машинами, но без аренды и долгов. Надежда: старые клиенты звонят и спрашивают, куда он пропал. Действие: на этой неделе договориться с другом, у которого свой гараж, и взять два заказа. Карта не обещает, что через год у Виктора будет новый сервис. Она показывает, что направление ясно и первый шаг доступен уже сейчас."], "det": [], "pairs": [], "person": {"Мысли": "Планы и образ желаемого будущего.", "Чувства": "Симпатия, доверие, желание сблизиться, иногда восхищение человеком на расстоянии.", "Намерения": "Готовность поддерживать связь, учиться, восстанавливаться.", "Поступки": "Смотрите, пишет ли человек, встречается ли и выполняет ли обещанное."}, "combo": [["Звезда и Башня", "Восстановление после удара. Башня рядом показывает, от чего человек восстанавливается, Звезда показывает, что первые спокойные шаги уже возможны."], ["Звезда и Дьявол", "Выход из зависимости, когда у человека появляется цель важнее привычки. Бывает и иначе: красивая надежда, которой человека удерживают."], ["Звезда и Умеренность", "Обе связаны с постепенным процессом и водой. На Умеренности ангел переливает воду между чашами и настраивает пропорции."], ["Звезда и Отшельник", "Поиск направления через обучение и размышление. Отшельник держит в фонаре звезду, здесь звезда сияет на небе для всех."], ["Звезда и Колесо Фортуны", "Открывается возможность, и есть понимание, куда её направить."], ["Звезда и Смерть", "После завершения появляется новый ориентир. Смерть закрывает, Звезда показывает, куда смотреть дальше."], ["Звезда и Повешенный", "Ожидание с надеждой. Проверьте, есть ли у человека действие, или он только ждёт."], ["Звезда и Маг", "Цель плюс навыки. Хорошее сочетание для начала дела, если навыки уже есть."], ["Звезда и Императрица", "Рост, восстановление, забота о себе. В вопросе о здоровье и самочувствии описывает постепенное возвращение сил."], ["Звезда и Дурак", "Открытая надежда на новое. Проверьте, есть ли у человека хоть какой-то план, или он идёт за звездой с закрытыми глазами."], ["Звезда и Сила", "Спокойная вера в себя. Человек не торопит события и выдерживает долгое восстановление."]], "pos": [], "open": "Звезда показывает ориентир, к которому можно идти долго, и первые спокойные действия после трудного периода.", "vis": "Под большой жёлтой восьмиконечной звездой и семью малыми звёздами обнажённая женщина стоит на колене у пруда. Одна нога на земле, другая на воде. Из одного кувшина она льёт воду в пруд, из другого на землю. Справа на дереве сидит птица, вдали холмы."}, "maj18": {"id": "maj18", "secs": {"Что изображено": "Верхнюю половину карты занимает большой жёлтый диск. Его окружают лучи: длинные чередуются с короткими.", "Детали и их смысл": "Разбирайте карту снизу вверх, как по ней идёт дорога: вода, рак, животные, башни, небо. Сначала назовите деталь так, как она нарисована, потом переходите к значению.", "Главный принцип": "Луна описывает положение, в котором сведений меньше, чем нужно для решения, а пустоты между ними заполняют воображение и страх. Человек при этом может двигаться вперёд, дорога ведь видна.", "Карта как человек": "Человек Луны чувствителен к переменам настроения, замечает интонации, видит яркие сны и запоминает их. При тревоге он начинает принимать собственное предположение за подтверждённый факт.", "Отношения, брак и семья": "В отношениях Луна показывает недоверие, тайну, неясный статус или притяжение, которое человек сам себе не может объяснить. Она не доказывает измену.", "Работа и проект": "На работе Луна показывает неясные обязанности, слухи, скрытые условия, интриги или задачу, в которой решение ещё формируется. Сотрудники обсуждают сокращение, руководство молчит; объём работы в договоре можно толковать по-разному.", "Деньги и имущество": "В денежном вопросе Луна указывает на то, что человек не видит всей картины. Это неизвестные платежи, комиссии мелким шрифтом, забытые долги.", "Ситуация и развитие событий": "Как характеристика ситуации Луна говорит: обстоятельства известны частично, чувства сильнее сведений, и это мешает трезво решать. В позиции развития событий карта обещает период неопределённости.", "Магия и диагностика": "В диагностической позиции Луна обращает внимание на сны, страхи, тревожность, размытые границы восприятия и скрытые связи между событиями. Карта показывает, что ситуация плохо видна самому спрашивающему и требует уточнения.", "Перевёрнутое положение (дополнительно)": "Перевёрнутая Луна читается в двух направлениях. В первом скрытая информация становится заметной: туман рассеивается, человек узнаёт то, о чём догадывался, страх ослабевает, потому что получил имя. Во втором тревога усиливается и мешает проверять факты: человек уже не задаёт вопросов, он уверен в худшем.", "Сочетания и сравнения": "Луна и Верховная Жрица. Обе карты связаны со скрытым, ночью и водой.", "Ошибки начинающих": "", "Практика и проверка": ""}, "err": ["объявлять любую Луну обманом или магическим воздействием. Ученик пугает человека, хотя сначала нужно назвать, что именно скрыто в вопросе.", "читать позицию страха как факт о внешнем мире. Карта описывает реакцию спрашивающего, и вывод о другом человеке или фирме из неё не следует."], "rem": ["Луна показывает неполный свет: часть видна, остальное дорисовывает страх, поэтому факты проверяют до решения."], "prac": [["Положите перед собой Луну и назовите по порядку, снизу вверх, всё, что встречает дорога. Затем скажите, какое из животных стоит слева.", "Вода, рак у её края, рыжая собака слева и светлый волк справа, две серые башни, горы вдали, над всем диск с полумесяцем и падающие капли. Две собаки нарисованы в других колодах; в колоде Райдера одно животное прирученное, другое дикое."], ["Ученик пишет по Луне в вопросе «Изменяет ли мне партнёр?»: «Да, карта обмана, есть соперница». Найдите ошибку.", "Луна показывает невыясненное и тревогу, она не называет вида скрытого и не указывает третьего человека. Корректный ответ: в отношениях есть тема, которую не обсуждают, и спрашивающий заполняет пробел подозрениями. Совет: прямой разговор о том, что изменилось. Вывод о сопернице из карты не следует."], ["Татьяна покупает дачу. Луна выпала в позиции «на что обратить внимание». Назовите три конкретные проверки.", "Подойдут любые проверки скрытого. Состояние фундамента, подвала и колодца, следы подтопления весной (водоём на карте). Документы на землю и дом, нет ли спора о границах участка. Разговор с соседями о том, почему продают дачу."], ["Возьмите вопрос «Как пройдёт мой первый месяц в новой школе?» (спрашивает учительница). Объясните Луну в позиции «что скрыто» и в позиции «чего я боюсь».", "В позиции скрытого: учительница не знает неписаных правил школы, отношений в коллективе и того, почему прежний педагог ушёл; ей стоит расспросить завуча и коллег. В позиции страха: она боится не справиться с классом и оказаться чужой; карта говорит о её тревоге, о самой школе вывода нет."]], "ex": ["Ира замечает, что муж последний месяц возвращается поздно и кладёт телефон экраном вниз. Она спрашивает: «Что происходит в наших отношениях?» Выпадает Луна. Ира сразу слышит в карте измену. Карта показывает другое: есть невыясненная тема, и муж о ней молчит. Это может быть роман, а может быть долг, проблема на работе, подготовка сюрприза или болезнь, о которой он не решается сказать. Совет по карте один: перестать собирать косвенные улики и задать прямой вопрос о том, что изменилось за месяц."], "det": [], "pairs": [], "person": {"Мысли": "Сомнения, догадки, несколько версий одного события.", "Чувства": "Тревога, сильное и неясное притяжение, уязвимость, смешанные переживания.", "Намерения": "Планы скрыты или ещё не сложились.", "Поступки": "Непрямые: он наблюдает, намекает, читает чужие страницы, избегает ясного разговора."}, "combo": [["Луна и Верховная Жрица", "Обе карты связаны со скрытым, ночью и водой. Верховная Жрица сидит спокойно, её знание хранится за завесой и не тревожит её."], ["Луна и Отшельник", "Отшельник несёт свой фонарь и освещает ближайший шаг. В Луне собственного света нет, только отражённый."], ["Луна и Звезда", "Звезда показывает ясный ориентир и действие у воды. Луна идёт после неё и показывает, что ориентир на время скрылся."], ["Луна и Дурак", "Оба идут в неизвестность. Дурак шагает легко и не боится."]], "pos": [], "open": "Луна даёт ночной свет: дорога видна, подробности скрыты, и пробелы между фактами легко заполняет страх.", "vis": "Большой диск с полумесяцем и лицом в профиль, глаза закрыты. С неба падают капли. Две серые башни по краям, горы вдали. Рыжая собака и светлый волк воют вверх. Из водоёма выползает рак, от воды между животными и башнями уходит к горам узкая дорога."}, "maj19": {"id": "maj19", "secs": {"Что изображено": "Над всей сценой стоит большое жёлтое солнце с человеческим лицом. Лицо обращено прямо к зрителю, глаза открыты.", "Детали и их смысл": "Разглядывайте карту от светила вниз: солнце, стена с подсолнухами, ребёнок, конь, знамя.", "Главный принцип": "Солнце показывает ясность, радость, открытость и результат, который можно увидеть. Карта помогает заметить, что уже получилось и что стало понятным.", "Карта как человек": "Человек Солнца заметен, легко показывает свои способности и делится радостью. С ним просто общаться, он говорит прямо и не держит камня за пазухой.", "Отношения, брак и семья": "В отношениях Солнце поддерживает ясность и взаимный интерес. Пара не прячется: о ней знают друзья и родные, планы обсуждаются вслух.", "Работа и проект": "В работе Солнце показывает признание, успешную презентацию или понятный результат проекта. Преподаватель заканчивает курс и получает первые отзывы учеников, программист выпускает приложение, и им начинают пользоваться.", "Деньги и имущество": "В финансах карта указывает на ясность доходов и возможность увидеть результат усилий. Человек знает, сколько зарабатывает, деньги приходят за понятную работу.", "Ситуация и развитие событий": "Как характеристика ситуации Солнце говорит: всё на виду, участники понимают, что происходит, и результат уже есть. В позиции развития событий карта обещает прояснение и видимый итог того, что делается сейчас.", "Магия и диагностика": "В диагностике Солнце показывает ясность состояния и проявленную личную силу. Человек хорошо себя чувствует, понимает, что с ним происходит, и способен действовать.", "Перевёрнутое положение (дополнительно)": "Перевёрнутое Солнце может показывать задержку признания, переоценку успеха или радость, которую человек сам обесценивает. Результат есть, но его не замечают или человек сам говорит «да это ерунда». Ещё один вариант: свет слишком яркий, человек хвастается, и окружающие устают от его успехов.", "Сочетания и сравнения": "Солнце и Звезда. Звезда показывает далёкий ориентир и надежду, Солнце освещает то, что стало видимым.", "Ошибки начинающих": "", "Практика и проверка": ""}, "err": ["обещать успех без условий. Назовите результат, к которому относится вопрос, и действия человека, от которых он зависит.", "читать любое Солнце как беременность. Ребёнок на рисунке передаёт открытость, а о зачатии карта ничего не сообщает.", "не замечать проблемной стороны. Солнце может описывать самолюбование или наивную откровенность, если позиция спрашивает о трудности."], "rem": ["Солнце показывает ясность, открытость и результат, который видят другие, но условия и сроки задают вопрос и расклад."], "prac": [["Найдите на карте три отличия рисунка Солнца от рисунка Луны в изображении самого светила.", "У Луны лицо в профиль, у Солнца анфас. У Луны глаза закрыты, у Солнца открыты. У Луны лучи только прямые, длинные и короткие, у Солнца прямые чередуются с волнистыми. Значение различий: прямой свет против отражённого, ясность против неполноты."], ["Вопрос: «Получу ли я повышение в этом году?» Выпало Солнце. Ученик отвечает: «Да, обязательно». Найдите ошибку и дайте свой ответ.", "Солнце показывает видимость результата и признание, но обещания с условием «обязательно» карта не даёт. Ответ: работа человека заметна и оценена, обстановка благоприятная, разговор о повышении стоит начинать открыто и с цифрами. Сроки и решение руководства из одной карты не следуют."], ["Опишите одну ситуацию сначала через Луну, затем через Солнце: какие сведения становятся ясными?", "Образец. Человек ждёт результатов собеседования. По Луне: компания молчит неделю, он перебирает догадки, думает, что провалился, и боится позвонить. По Солнцу: приходит письмо с ответом, условия названы, он понимает, что решать дальше. Ясными стали факты: решение компании, зарплата, срок выхода."], ["Женщина спрашивает: «Как сложатся наши отношения с новым соседом по даче?» Выпало Солнце. Объясните, почему в ответе не нужно говорить о детях.", "Вопрос касается соседских отношений. Ребёнок на рисунке описывает открытость и радость контакта. Ответ: отношения будут простыми и дружелюбными, договорённости о заборе или воде легко обсудить прямо. Тема детей из вопроса не следует, и вносить её трактовка не должна."]], "ex": ["Марина и Денис встречаются полгода. Марина спрашивает: «Как Денис относится к нашим отношениям?» Выпадает Солнце. Карта описывает открытое, тёплое отношение, которое видно по поступкам. По жизни это так: Денис познакомил Марину с родителями, выкладывает общие фотографии, на выходных зовёт её к друзьям. Отношение не спрятано, его наблюдают другие люди. О свадьбе карта прямо не говорит. Если Марина хочет знать о браке, нужен отдельный вопрос, и ответ на него ищут в позиции, которая к браку относится.", "Алексей два года вёл в своём отделе внутренний проект по учёту склада, о котором знали трое коллег. В апреле его систему показали на общем собрании, и директор попросил внедрить её во всех филиалах. Алексей спрашивает, как будет развиваться его положение. Солнце описывает момент, когда работа вышла из-за стены отдела на общий обзор. Карта говорит о признании и видимости. Повышение она не гарантирует, его Алексею нужно обсудить с руководством прямо, и Солнце поддерживает такой открытый разговор."], "det": [["Солнце", "лицо анфас, глаза открыты", "прямой свет, всё видно"], ["Ребёнок", "обнажён, руки раскинуты", "открытость, нечего скрывать"], ["Венок и перо", "цветы и красное перо", "радость, лёгкость начала"], ["Конь", "белый, без седла и узды", "сила, которая идёт сама"], ["Знамя", "большое красное полотнище", "заявление о себе, видно издали"], ["Стена", "серая каменная кладка", "граница освоенного места"], ["Подсолнухи", "выросли выше стены", "созревший, видимый результат"]], "pairs": [], "person": {"Мысли": "Ясное понимание и позитивный план.", "Чувства": "Симпатия, тепло, удовольствие от общения, гордость за сделанное.", "Намерения": "Стремление к открытому контакту, к тому, чтобы о деле или отношениях узнали другие.", "Поступки": "Он предлагает встречу, знакомит с близкими, выкладывает работу, прямо сообщает о своём решении."}, "combo": [["Солнце и Звезда", "Звезда показывает далёкий ориентир и надежду, Солнце освещает то, что стало видимым. Звезда спрашивает «куда идти», Солнце отвечает «вот что получилось»."], ["Солнце и Луна", "Это пара для сравнения одной ситуации. Луна показывает её в ночном свете, с догадками и страхом, Солнце показывает её днём, когда стало ясно, что произошло."], ["Солнце и Дурак", "У обоих красное перо и лёгкость. Дурак только выходит и не знает, что впереди."], ["Солнце и Смерть", "Обе карты показывают белого коня. Всадник Смерти в доспехах завершает прежнее, ребёнок Солнца обнажён и открывает новое."], ["Солнце и Колесница", "Обе показывают успех и движение. Колесничий стоит в доспехах и удерживает двух сфинксов волей."], ["Солнце и Императрица", "Обе связаны с ростом и плодами. Императрица описывает сам процесс роста, заботу, достаток."], ["Солнце и Маг, Правосудие", "С Магом Солнце даёт заметное применение навыка: выступление, удачная демонстрация. С Правосудием помогает открыто обсудить условия и увидеть факты, например подписать договор, где всё прописано."]], "pos": [], "open": "Солнце освещает сцену целиком: результат виден, человек открыт, и то, что было спрятано, стало понятным.", "vis": "Большое солнце с лицом анфас, прямые и волнистые лучи. Под ним серая каменная стена, над стеной подсолнухи. Обнажённый ребёнок в венке с красным пером раскинул руки и сидит без седла на белом коне. Он держит древко с большим красным знаменем."}, "maj20": {"id": "maj20", "secs": {"Что изображено": "Алексей давно откладывал разговор о закрытии семейного дела. Когда срок аренды подошёл к концу, он собрал документы и пригласил родственников обсудить результаты.", "Детали и их смысл": "Первым замечают ангела и трубу, затем взгляд опускается к людям. Новичок часто останавливается на кресте и читает карту как обещание наказания.", "Главный принцип": "Суд показывает возвращение важного вопроса и необходимость на него ответить. Карта строится на сочетании двух событий: сигнал пришёл, человек откликнулся.", "Карта как человек": "Человек Суда способен пересмотреть прежние решения и откликнуться на перемены. Он признаёт результат, собирает факты и принимает новую ответственность.", "Отношения, брак и семья": "В отношениях Суд может показать возвращение человека из прошлого или важный разговор о будущем пары. Бывший партнёр пишет через два года, или супруги наконец садятся обсудить то, о чём молчали со свадьбы.", "Работа и проект": "В работе Суд показывает итог собеседования, ответ на заявку, пересмотр профессионального решения или возвращение к отложенному проекту. Компания вспоминает о кандидате, которому отказала полгода назад.", "Деньги и имущество": "В деньгах Суд привлекает внимание к старым обязательствам, возвратам и расчётам. Это налоговый вычет за прошлые годы, возврат долга, который давно считали потерянным, пересчёт пенсии, требование оплатить старую задолженность.", "Ситуация и развитие событий": "Как ситуация Суд описывает поворотный момент, к которому привела прежняя история. Событие приходит в виде новости, вызова, приглашения.", "Магия и диагностика": "В диагностике Суд указывает на возвращение старой темы и необходимость рассмотреть историю вопроса. Если человек приходит с жалобой, что дела повторяются по кругу, карта предлагает посмотреть, какой вопрос остался без ответа и почему он всплывает.", "Перевёрнутое положение (дополнительно)": "Перевёрнутый Суд показывает отказ отвечать на важный вопрос, страх оценки или повторное рассмотрение незавершённого дела. Человек слышит сигнал и прячется: не открывает письма, переносит встречу, говорит, что подумает позже. Иногда перевёрнутая карта описывает решение, принятое под давлением, без настоящего пересмотра прошлого.", "Сочетания и сравнения": "Суд и Правосудие. Правосудие сравнивает факты и условия, взвешивает, кто прав по договору.", "Ошибки начинающих": "", "Практика и проверка": ""}, "err": ["называть Суд обязательным наказанием. Карта показывает оценку и ответ, а итог оценки может быть хорошим, плохим или смешанным.", "автоматически обещать возвращение бывшего партнёра. Суд показывает, что тема вернулась, а восстановление отношений зависит от решений обоих людей.", "читать карту как религиозное утверждение о спрашивающем. Христианский сюжет помогает понять рисунок, но вопрос о вере человека карта не решает.", "путать Суд с началом с чистого листа. Карта поднимает то, что уже было; новое, если начнётся, вырастет из ответа на старый вопрос."], "rem": ["Суд возвращает важный вопрос и требует на него ответить."], "prac": [["Найдите на карте три фигуры переднего плана и запишите, что делает руками каждая. Затем найдите на заднем плане другие фигуры и сосчитайте, сколько вы их видите.", "Мужчина слева сложил ладони перед грудью, женщина справа тянет обе руки к ангелу, ребёнок в середине поднял руки. На заднем плане видны ещё несколько фигур с поднятыми руками, среди них детская. Важнее числа сам факт: поднимается больше одной семьи. Уэйт отдельно отмечал, что воскресших на этой карте больше трёх."], ["Найдите ошибку в трактовке: «Выпал Суд, значит, вас накажут за прошлые поступки, и бывший партнёр обязательно вернётся».", "В трактовке две ошибки. Первая: Суд описывает оценку и ответ, наказания на карте нет, люди поднимаются навстречу звуку. Вторая: возвращение темы не равно возвращению человека. Правильнее сказать: старая история снова требует внимания, и нужно решить, как на неё ответить. Будет ли бывший партнёр рядом, карта не говорит."], ["На вопрос «Почему мне снова предлагают работу, от которой пришлось отказаться два года назад?» выпал Суд; объясните ответ через три детали рисунка.", "Труба: предложение пришло извне, как сигнал, и его нельзя пропустить. Открытые гробы: прежнее решение было отложено, вопрос о работе остался открытым. Поднятые руки: от человека ждут отклика, сейчас нужно ответить. Карта не говорит, нужно ли соглашаться. Она советует вспомнить, почему был отказ два года назад, и проверить, изменились ли эти причины."], ["Возьмите старое дело из своей жизни и запишите три строки: какой сигнал вернул его, какой итог уже известен, какое решение ещё требуется.", "Образец записи: «Сигнал: пришло письмо из банка о старом счёте. Итог: счёт открыт пять лет назад, по нему остался долг 1200 рублей. Решение: закрыть счёт или оставить для зарплаты». Проверьте, что в третьей строке стоит действие. Если там чувство, например «мне стыдно», допишите, что вы сделаете."]], "ex": ["Марина и Олег развелись пять лет назад и с тех пор общались только о сыне. Сыну исполнилось семнадцать, он собирается поступать в другом городе, и нужно решить, кто оплачивает общежитие. Марина спрашивает: «Что происходит в наших отношениях с бывшим мужем?» Выпадает Суд. Карта показывает, что старая общая история вернулась через сына и требует совместного ответа. Возобновления романа она не обещает. Полезный вопрос для следующей карты: какой разговор Марине нужно начать первой?"], "det": [], "pairs": [], "person": {"Мысли": "Переоценка прошлого.", "Чувства": "Сильный отклик на новость или встречу.", "Намерения": "Вернуться к вопросу и принять решение.", "Поступки": "Звонок, разговор, оформление ответа, завершение давнего дела."}, "combo": [["Суд и Правосудие", "Правосудие сравнивает факты и условия, взвешивает, кто прав по договору. Суд показывает отклик на итог или возвращение значимой темы."], ["Суд и Колесо Фортуны", "Колесо Фортуны даёт смену обстоятельств и цикл, ситуация поворачивается независимо от человека. Суд обращает внимание на решение после рассмотрения прошлого."], ["Суд и Умеренность", "На обеих картах крылатый ангел. Уэйт сам предлагал сравнить Суд с Умеренностью."], ["Суд и Смерть", "Смерть закрывает прежнюю форму. Суд поднимает закрытое и спрашивает, что с ним делать."], ["Суд и Отшельник", "Отшельник ищет ответ в одиночестве с фонарём, на Суде сигнал приходит извне. Вместе они описывают долгие раздумья, которые прервало письмо или звонок."]], "pos": [], "open": "Суд показывает, как отложенный вопрос возвращается и требует ответа: человек слышит сигнал и решает, что сделать с прошлым.", "vis": "В облаках крылатый ангел трубит в золотую трубу, к ней прикреплено белое знамя с красным крестом. Внизу из открытых гробов поднимаются серые обнажённые люди: мужчина слева, женщина справа, ребёнок между ними спиной к зрителю. Дальше на воде видны другие поднявшиеся фигуры, на горизонте белые горы."}, "maj21": {"id": "maj21", "secs": {"Что изображено": "Елена закончила обучение, сдала последнюю работу и получила документ. Теперь она может рассказать, чему научилась, и использовать этот навык в работе.", "Детали и их смысл": "Взгляд сначала попадает в центр, на фигуру. Затем он скользит по венку и упирается в углы.", "Главный принцип": "Мир показывает завершённый этап и собранный результат. Признак этой карты в том, что части дела сошлись: работа сдана, документы подписаны, все стороны согласны.", "Карта как человек": "Человек Мира видит разные стороны дела и способен собрать их в завершённую работу. Он понимает, какие обязанности у участников и когда задача выполнена.", "Отношения, брак и семья": "В отношениях Мир показывает согласованность и завершение важного этапа пары. Для одной пары это окончание ремонта в общей квартире, для другой оформление брака, для третьей совместное решение о переезде.", "Работа и проект": "В работе Мир показывает завершённый проект, выпуск продукта, получение квалификации или сотрудничество с людьми из других мест. Книга вышла из типографии, приложение опубликовано, ремонт объекта принят заказчиком.", "Деньги и имущество": "В деньгах Мир указывает на итог сделки или закрытие финансового обязательства. Последний платёж по кредиту, получение оплаты за весь проект, завершённый раздел общего счёта.", "Ситуация и развитие событий": "Как ситуация Мир описывает момент, когда этап закончен и результат на руках. Дальше результат используют для следующего дела или застывают в нём.", "Магия и диагностика": "В диагностике Мир показывает собранность, завершение работы и восстановление границ. Если человек проходил долгую очистку или курс практик, карта может описывать момент, когда этап закончен и его результат держится.", "Перевёрнутое положение (дополнительно)": "Перевёрнутый Мир показывает незавершённую часть дела: документы ещё не подписаны, работа не сдана или человек сам не признаёт достигнутый итог. Венок как будто разорван в одном месте. Уточните, какого конкретного действия не хватает для завершения.", "Сочетания и сравнения": "Мир и Смерть. Смерть закрывает прежнюю форму, Мир показывает собранный итог этапа.", "Ошибки начинающих": "", "Практика и проверка": ""}, "err": ["считать любую карту Мира обязательным путешествием за границу. Начните с вопроса и определите, какой этап завершается.", "читать Мир как обещание вечного счастья. Карта описывает завершённый этап, а за ним начнётся следующий со своими задачами.", "путать Мир с Солнцем. Солнце показывает, что результат виден и радует; Мир показывает, что он собран, оформлен и им уже пользуются.", "считать дело законченным, когда последнего шага ещё нет. Проверьте подписи и договорённости: без них Мир описывает близость к завершению."], "rem": ["Мир показывает завершённый этап и результат, который можно использовать дальше."], "prac": [["Положите рядом Мир и Колесо Фортуны. Найдите четыре существа на каждой карте и запишите два отличия в том, как они изображены.", "Места совпадают: человек вверху слева, орёл вверху справа, бык внизу слева, лев внизу справа. Отличия: на Колесе у существ есть крылья и книги, на Мире видны только головы в облаках."], ["Найдите ошибку: «Выпал Мир, значит, вы поедете за границу и будете счастливы всю жизнь».", "Две ошибки. Путешествие возможно только если вопрос о поездке или переезде, сама карта его не назначает. Мир описывает завершённый этап, а вечное счастье не следует ни из одной карты. Правильнее: в вопросе что-то большое доведено до конца; нужно понять, что именно."], ["На вопрос «Почему я не могу закончить диссертацию?» выпал перевёрнутый Мир; объясните, что ищет эта карта в ситуации.", "Перевёрнутый Мир показывает разорванный венок: почти всё собрано, но последний узел не завязан. Нужно найти конкретный недостающий шаг: глава, которую не сдают; подпись руководителя; страх выйти на защиту. О качестве диссертации карта ничего не говорит."], ["Выберите завершённое дело и запишите, что было сделано, какой результат получен и где вы его используете.", "Образец: «Сделано: прошли курс английского, сдали экзамен. Результат: сертификат уровня B2. Использование: отправили резюме в две компании с иностранными клиентами». Пустая третья строка значит, что результатом пока не пользуются."]], "ex": ["Сёстры Ольга и Наташа три года спорили, где будет жить их мама после операции. Ольга хотела забрать её к себе, Наташа предлагала нанять сиделку в мамином доме. Наконец собрались втроём вместе с мамой и договорились: зимой мама живёт у Ольги, летом в своём доме, а Наташа оплачивает сиделку на эти месяцы. Решение записали и подписали все трое. Мир на вопрос «Что с нашим семейным решением?» описывает этот итог: голос каждой стороны учтён, как четыре существа по углам венка.", "Семья Кравцовых переезжала из Самары в Екатеринбург полгода. Отец нашёл работу, мать перевела документы детей в новую школу, квартиру в Самаре продали, новую сняли и обставили. В сентябре дети пошли в школу, а мать записалась к местному врачу. Вопрос «Чем закончится наш переезд?», выпал Мир. Карта описывает завершённый переход: семья уже живёт в новом городе и обустроилась в нём. Приживутся ли дети, покажет другая позиция."], "det": [["В центре", "колесо со знаками", "человек в венке"], ["Движение", "колесо вращается, фигуры поднимаются и опускаются", "человек танцует сам"], ["Кто управляет", "обстоятельства", "сам человек"], ["Существа", "крылатые, каждое читает книгу", "только головы, книг нет"], ["Форма центра", "круг, который крутится", "овал, который замкнут"], ["Вопрос карты", "что повернулось?", "что завершено?"]], "pairs": [], "person": {"Мысли": "Понимание целого и готовность подвести итог.", "Чувства": "Удовлетворение, принятие, спокойствие.", "Намерения": "Завершить дело или закрепить договорённость.", "Поступки": "Сдача проекта, оформление результата, завершение переезда, достижение общего решения."}, "combo": [["Мир и Смерть", "Смерть закрывает прежнюю форму, Мир показывает собранный итог этапа. Вместе они описывают окончание, после которого остаётся результат: развод, где имущество разделено честно; закрытие компании, где все долги погашены."], ["Мир и Суд", "Суд возвращает значимый вопрос для ответа, Мир помогает увидеть результат после выполненной работы. В последовательности Суд, затем Мир читается так: на старый вопрос ответили, и дело закрыто."], ["Мир и Колесо Фортуны", "Колесо поворачивает обстоятельства, Мир собирает итог. Колесо, а за ним Мир, может описывать удачный поворот, которым человек воспользовался до конца."], ["Мир и Колесница", "Вместе они показывают прибытие к цели после движения."], ["Мир и Дурак", "Первая и последняя карты ряда. Рядом они часто описывают окончание одного этапа и начало следующего: диплом получен, и человек уезжает в новый город."], ["Мир и Маг", "У Мага один жезл и стол с инструментами, он начинает работу. У Мира два жезла, и работа сделана."], ["Мир и Солнце", "Солнце показывает ясность и видимый результат, радость от успеха. Мир показывает, что результат завершён и встроен в жизнь."], ["Мир и Повешенный", "Сравните ноги. У Повешенного одна нога согнута за другой, он висит вниз головой."]], "pos": [], "open": "Мир показывает завершённый этап: части дела собраны, результат получен, и им можно пользоваться дальше.", "vis": "Внутри овального зелёного венка, перевязанного сверху и снизу красными лентами, танцует обнажённая фигура с лиловым шарфом через тело. В каждой руке у неё по светлому жезлу. В четырёх углах карты среди облаков видны головы человека, орла, быка и льва, те же существа, что на Колесе Фортуны."}};
window.LOPT={"key": "L6", "kick": "Урок 6 · тренажёры", "title": "Старшие арканы XV–XXI", "sub": "13 тренажёров по картам урока. На полный проход уходит 40–60 минут. Рекомендуем идти по порядку и добиваться 85% в каждом.", "ids": ["maj15", "maj16", "maj17", "maj18", "maj19", "maj20", "maj21"]};
(function(){var O=window.LOPT,D=DECK,SH=TRU.shuf,P=function(a){return a[Math.floor(Math.random()*a.length)];};var ids=O.ids;O.extra=O.extra||[];
O.extra.push({id:'order',title:'Порядок арканов',fmt:'расставьте по номерам',desc:'Пять арканов урока вперемешку. Расставьте их по номерам, от меньшего к большему.',mode:'order',count:10,
 gen:function(){var s=SH(ids).slice(0,5).sort();return {q:'Нажимайте на арканы в порядке номеров.',items:s.map(function(i){return D.name(i);}),e:s.map(function(i){return D.by[i].rom+'. '+D.name(i);}).join(' → ')};}});
O.extra.push({id:'num',title:'Номер аркана',fmt:'впишите номер',desc:'Видите карту без подписи. Впишите её номер арабской цифрой.',mode:'fill',count:16,
 gen:function(){var i=P(ids);var n=parseInt(i.slice(3),10);return {q:'Какой номер у аркана «'+D.name(i)+'»? Впишите цифрой.',a:[String(n)],e:'Аркан '+D.by[i].rom+', то есть '+n+'.'};}});
})();

(function(){
var D=DECK,P=function(a){return a[Math.floor(Math.random()*a.length)];},SH=TRU.shuf,CF=window.CF,O=window.LOPT;
var IDS=O.ids,ALL=IDS.map(function(i){return CF[i];});
function nm(id){return D.name(id);}
function cut(s,n){n=n||220;if(!s)return '';if(s.length<=n)return s;var c=s.slice(0,n);var p=c.lastIndexOf('. ');return (p>80?c.slice(0,p+1):c.replace(/\s\S*$/,'')+'…');}
var SUITW=['Мечей','Жезлов','Кубков','Пентаклей'];
function root(w){var r=w;if(r.length>4)r=r.slice(0,-1);else if(r.length===4&&/[аяеиоуыэюё]$/.test(r))r=r.slice(0,-1);if(/[ьй]$/.test(r))r=r.slice(0,-1);return r.replace(/[ёе]/g,'[ёе]')+'[а-яё]{0,3}';}
function rootRe(name){return name.split(' ').map(root).join('\\s+');}
function mask(t,id){if(!t)return t;var n=nm(id);n.split(' ').forEach(function(w){if(w.length<3||SUITW.indexOf(w)>=0)return;var re=new RegExp('(^|[^а-яёА-ЯЁ])('+root(w)+')(?![а-яё])','g');t=t.replace(re,'$1«…»');});
  t=t.replace(/«…»\s+«…»/g,'«…»');if(n==='Правосудие')t=t.replace(/Справедливост[а-яё]*/g,'«…»');return t;}
function maskAll(t){IDS.forEach(function(i){t=mask(t,i);});return t;}
function others(id,k){return SH(IDS.filter(function(x){return x!==id;})).slice(0,k);}
function mcq(q,right,wrong,extra){var o=[right].concat(wrong);var it={q:q,o:o,a:0};for(var k in extra)it[k]=extra[k];return it;}
var SPH=[['love','Отношения','отношения и семью'],['work','Работа','работу'],['money','Деньги','деньги'],['sit','Ситуация','развитие ситуации'],['mag','Магия','магическую диагностику'],['rev','Перевёрнутое','перевёрнутое положение']];
function sec(c,pref){for(var k in c.secs)if(k.indexOf(pref)===0&&c.secs[k])return c.secs[k];if(pref==='Работа')for(var k2 in c.secs)if(k2.indexOf('Работа и деньги')===0)return c.secs[k2];if(pref==='Деньги')for(var k3 in c.secs)if(k3.indexOf('Работа и деньги')===0)return null;return null;}
var T=[];
// 1 flash
T.push({id:'flash',title:'Карточки для запоминания',fmt:'флеш-карты',desc:'Смотрите на рисунок, вспоминаете принцип карты и как она ведёт себя в человеке, потом переворачиваете.',mode:'flash',count:IDS.length*2,
 gen:function(){var c=P(ALL);var p=c.person||{};return {img:c.id,front:'Что это за карта и в чём её главный принцип?',back:nm(c.id)+'\n\n'+(c.open||'')+'\n\n'+Object.keys(p).map(function(k){return k+': '+p[k];}).join('\n'),showName:false};}});
// 2 blitz
T.push({id:'blitz',title:'Блиц: узнай по рисунку',fmt:'на время, 6 секунд',desc:'Название и номер на рисунке закрыты. Узнайте карту по сюжету.',mode:'mcq',timer:6,count:24,
 gen:function(){var c=P(ALL);return mcq('Какая это карта?',nm(c.id),others(c.id,3).map(nm),{img:[c.id],noname:true,big:true,e:c.open});}});
// 3 principle
T.push({id:'princ',title:'Главный принцип',fmt:'выбор из четырёх',desc:'Под картой четыре формулировки принципа. Только одна написана для неё.',mode:'mcq',count:20,
 gen:function(){var c=P(ALL);return mcq('Какой принцип описывает эту карту?',maskAll(c.open),others(c.id,3).map(function(x){return maskAll(CF[x].open);}),{img:[c.id],noname:true,e:c.rem[0]||''});}});
// 4 desc
T.push({id:'desc',title:'Карта по описанию рисунка',fmt:'описание → карта',desc:'Читаете описание рисунка, где название закрыто, и выбираете карту.',mode:'mcq',count:20,
 gen:function(){var c=P(ALL);return mcq('Какую карту описывает этот текст?',nm(c.id),others(c.id,3).map(nm),{story:maskAll(c.vis&&c.vis.length>80?c.vis:(c.secs['Что изображено']||c.vis))});}});
// 5 detail
var DET=[];ALL.forEach(function(c){(c.det||[]).forEach(function(r){if(r[2]&&r[2].length>8)DET.push({id:c.id,d:r[0],w:r[1],r:r[2]});});});
if(DET.length>=8)T.push({id:'detail',title:'Деталь рисунка',fmt:'деталь → как читается',desc:'Деталь конкретной карты и четыре прочтения. Нужно выбрать то, что из этой детали следует.',mode:'mcq',count:24,
 gen:function(){var x=P(DET);var w=SH(DET.filter(function(y){return y.r!==x.r&&y.d!==x.d;})).slice(0,3).map(function(y){return y.r;});return mcq(nm(x.id)+'. Деталь: «'+x.d+'»'+(x.w&&x.w!==x.d?' ('+x.w+')':'')+'. Как она читается?',x.r,w,{img:[x.id]});}});
// 6 person match
var PK=['Мысли','Чувства','Намерения','Поступки'];
T.push({id:'person',title:'Карта как человек',fmt:'соедините пары',desc:'Четыре карты и четыре описания: что человек думает, чувствует, хочет или делает. Соедините.',mode:'match',count:10,
 gen:function(){var k=P(PK);var cs=SH(ALL.filter(function(c){return c.person&&c.person[k];})).slice(0,4);return {q:k+' человека. Соедините карту с описанием.',pairs:cs.map(function(c){return ['#'+c.id,maskAll(c.person[k])];})};}});
// 7 sphere
T.push({id:'sphere',title:'Карта в теме вопроса',fmt:'тема → прочтение',desc:'Одна карта, конкретная тема вопроса и четыре прочтения. Три из них написаны для других карт этой же темы.',mode:'mcq',count:24,
 gen:function(){for(var g=0;g<50;g++){var c=P(ALL),s=P(SPH.slice(0,5));var r=sec(c,s[1]);if(!r)continue;var w=others(c.id,6).map(function(x){return sec(CF[x],s[1]);}).filter(Boolean).slice(0,3);if(w.length<3)continue;
  return mcq('Вопрос про '+s[2]+'. Выпала эта карта. Какое прочтение ей подходит?',maskAll(cut(r,260)),w.map(function(x){return maskAll(cut(x,260));}),{img:[c.id],e:nm(c.id)});}}});
// 8 reversed
T.push({id:'rev',title:'Перевёрнутое положение',fmt:'карта вниз головой',desc:'Карта лежит перевёрнутой. Выберите описание перевёрнутого положения именно этой карты.',mode:'mcq',count:16,
 gen:function(){var c=P(ALL.filter(function(c){return sec(c,'Перевёрнутое');}));return mcq('Карта выпала перевёрнутой. Что это скорее значит?',maskAll(cut(sec(c,'Перевёрнутое'),300)),others(c.id,5).map(function(x){return sec(CF[x],'Перевёрнутое');}).filter(Boolean).slice(0,3).map(function(t){return maskAll(cut(t,300));}),{img:[c.id+'r'],e:nm(c.id)});}});
// 9 story (examples)
var EX=[];ALL.forEach(function(c){(c.ex||[]).forEach(function(t){EX.push({id:c.id,t:t});});(c.prac||[]).forEach(function(p){});});
T.push({id:'story',title:'Какая карта в этой истории',fmt:'история → карта',desc:'Короткая история из практики, название карты закрыто. По сюжету определите, какая карта выпала.',mode:'mcq',count:Math.min(EX.length,16),
 gen:function(){var x=P(EX);return mcq('Какая карта стоит за «…» в этой истории?',nm(x.id),others(x.id,3).map(nm),{story:mask(cut(x.t,700),x.id)});}});
// 10 combo
var CB=[];ALL.forEach(function(c){(c.combo||[]).forEach(function(p){if(p[1].length>30)CB.push({id:c.id,h:p[0],t:p[1]});});});
if(CB.length>=6)T.push({id:'combo',title:'Сочетания и сравнения',fmt:'пара → смысл',desc:'Названа пара карт. Выберите, что о ней сказано в уроке.',mode:'mcq',count:Math.min(CB.length,20),
 gen:function(){var x=P(CB);return mcq((new RegExp(rootRe(nm(x.id).split(' ')[0])).test(x.h)?'':nm(x.id)+': ')+x.h.replace(/\.$/,'')+'. Что сказано в уроке про это сочетание?',x.t,SH(CB.filter(function(y){return y.h!==x.h;})).slice(0,3).map(function(y){return y.t;}),{img:[x.id]});}});
// 11 positions (minors)
var PS=[];ALL.forEach(function(c){(c.pos||[]).forEach(function(p){PS.push({id:c.id,h:p[0],t:p[1]});});});
if(PS.length>=8)T.push({id:'pos',title:'Карта в позиции расклада',fmt:'позиция → прочтение',desc:'Карта стоит в определённой позиции расклада. Какое прочтение подходит этой карте в этой позиции?',mode:'mcq',count:20,
 gen:function(){var x=P(PS);var w=SH(PS.filter(function(y){return y.id!==x.id&&y.h===x.h;}));if(w.length<3)w=w.concat(SH(PS.filter(function(y){return y.id!==x.id&&y.h!==x.h;})));return mcq('Позиция: «'+x.h+'». Как читается эта карта?',maskAll(x.t),w.slice(0,3).map(function(y){return maskAll(y.t);}),{img:[x.id],e:nm(x.id)});}});
// 12 errors tf
var TF=[];ALL.forEach(function(c){(c.err||[]).forEach(function(t){var s=t.split(/(?<=[.!?])\s+/);TF.push({s:'Типичное толкование: «'+s[0]+'» ('+nm(c.id)+'). Это верный подход?',a:false,e:s.slice(1).join(' '),img:[c.id]});});(c.rem||[]).forEach(function(t){TF.push({s:t,a:true,img:[c.id]});var o=P(IDS.filter(function(x){return x!==c.id;}));TF.push({s:t.replace(new RegExp(rootRe(nm(c.id))),nm(o)),a:false,e:'Это сказано про карту «'+nm(c.id)+'».',img:[o]});});});
T.push({id:'tf',title:'Верно или ошибка',fmt:'да / нет',desc:'Утверждения и типичные толкования начинающих. Решите, можно ли так читать карту.',mode:'tf',items:TF,count:Math.min(TF.length,24)});
// 13 cases
var CS=[];ALL.forEach(function(c){(c.prac||[]).forEach(function(p){CS.push({story:p[0],img:[c.id],q:'Ответьте письменно, затем откройте разбор.',model:p[1]});});});
T.push({id:'case',title:'Практика с разбором',fmt:'письменный ответ',desc:'Задания из урока. Пишете свой ответ, открываете образец и честно оцениваете, совпало ли по сути.',mode:'case',items:CS,count:Math.min(CS.length,12)});
(O.extra||[]).forEach(function(x){T.push(x);});
window.LESSON={key:O.key,kick:O.kick,title:O.title,sub:O.sub.replace('13 ',T.length+' '),trainers:T};
})();
